			Insert into CRMUSER.MISCELLANEOUSINFO   (MISCELLANEOUSID, BANK_ID, PSYCHOGRAPHICID, TYPE, STRTEXT1, STRTEXT10, DTDATE1, DBFLOAT1, DBFLOAT2, DBFLOAT3, DBFLOAT4, CORE_CUST_ID, ENTITY_CRE_FLG, ORGKEY, TMDATE)
